const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define farmland area southeast of Calgary, Alberta
  const calgary = ee.Geometry.Point([-113.9, 50.9]); // SE of Calgary
  const region = calgary.buffer(20000); // 20km radius for farmland area

  const date1 = '2025-08-19';
  const date2 = '2025-08-24';

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  }

  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  // Try Sentinel-2 for first date
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .map(maskS2clouds);

  let size1 = await col1.size().getInfo();
  console.log(`Date1 (${date1}) Sentinel-2 images: ${size1}`);

  // Try Sentinel-2 for second date
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .map(maskS2clouds);

  let size2 = await col2.size().getInfo();
  console.log(`Date2 (${date2}) Sentinel-2 images: ${size2}`);

  // If no data, try wider date range or Landsat
  if (size1 === 0 || size2 === 0) {
    console.log('Trying wider date range (±3 days)...');
    col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(ee.Date(date1).advance(-3, 'day'), ee.Date(date1).advance(3, 'day'))
      .map(maskS2clouds);

    col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(ee.Date(date2).advance(-3, 'day'), ee.Date(date2).advance(3, 'day'))
      .map(maskS2clouds);

    size1 = await col1.size().getInfo();
    size2 = await col2.size().getInfo();
    console.log(`Wider range - Date1: ${size1}, Date2: ${size2}`);
  }

  if (size1 === 0 || size2 === 0) {
    console.log('No images found for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate NDVI for both dates
  const ndvi1 = calculateNDVI(col1.median());
  const ndvi2 = calculateNDVI(col2.median());

  // Check valid pixel counts
  const stats1 = await ndvi1.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await ndvi2.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count1 = stats1['NDVI_count'];
  const mean1 = stats1['NDVI_mean'];
  const count2 = stats2['NDVI_count'];
  const mean2 = stats2['NDVI_mean'];

  console.log(`Aug 19: NDVI=${mean1?.toFixed(3)}, Pixels=${count1}`);
  console.log(`Aug 24: NDVI=${mean2?.toFixed(3)}, Pixels=${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid calculations
  if (mean1 === null || mean1 === undefined || isNaN(mean1) ||
      mean2 === null || mean2 === undefined || isNaN(mean2) ||
      mean1 > 1 || mean1 < -1 || mean2 > 1 || mean2 < -1) {
    console.log('Invalid NDVI values calculated.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Determine if greenness decreased
  const decrease = mean2 - mean1;
  console.log(`NDVI change: ${decrease.toFixed(3)}`);

  if (decrease < 0) {
    console.log('Vegetation greenness decreased.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation greenness did not decrease.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
